import {TYPES,validateWorld,dateOrdinal,removeEntity,treeLevels} from '/model.mjs';
const $=(s,root=document)=>root.querySelector(s), $$=(s,root=document)=>[...root.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID();
const icons={home:'M3 10 12 3l9 7v11h-6v-7H9v7H3Z',cards:'M4 4h7v7H4zM14 4h7v7h-7zM4 14h7v7H4zM14 14h7v7h-7z',map:'m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2ZM9 3v16M15 5v16',timeline:'M3 12h18M6 8v8M12 5v14M18 8v8',calendar:'M4 5h16v16H4zM4 10h16M8 3v4M16 3v4',relations:'M6 6h.01M18 6h.01M12 18h.01M6 6l6 12 6-12ZM9 6h6',tree:'M12 3v7M5 14v-4h14v4M3 14h4v6H3zM17 14h4v6h-4zM10 2h4v5h-4z',canvas:'M3 3h18v18H3zM7 8h4v5H7zM14 12h4v5h-4z',wiki:'M12 5c-3-2-6-2-9-1v16c3-1 6-1 9 1 3-2 6-2 9-1V4c-3-1-6-1-9 1Zm0 0v16',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M19 5l-2 2M7 17l-2 2',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14Zm5 12 6 6',plus:'M12 4v16M4 12h16',close:'M5 5l14 14M19 5 5 19',arrow:'M4 12h16M14 6l6 6-6 6',leaf:'M20 3C7 2 2 9 5 16s15 5 15-13ZM5 20 16 8',check:'m4 12 5 5L20 6'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[n]||icons.cards}"/></svg>`;
const glyph={Character:'♙',Location:'⌂',Faction:'⚑',Creature:'❧',Ecology:'♧',Item:'✧',Event:'◷',Lore:'☾'};
let w,token,revision,route='home',filter='All',selected='',editing=false,mapId='',boardId='',wikiId='',mapMode='',pendingPoints=[],calendarYear=842,calendarMonth=1,saveTimer,saving=false,dirty=false,checkpoint=false,saveError='',generation=0;
const app=$('#app'),inspector=$('#inspector'),dialog=$('#dialog');
const entity=id=>w.entities.find(e=>e.id===id);
const currentMap=()=>w.maps.find(m=>m.id===mapId)||w.maps[0];
const currentBoard=()=>w.boards.find(b=>b.id===boardId)||w.boards[0];
const dateText=d=>d?`${d.day} ${w.calendar.months[d.month]?.name||'?'} ${d.year} ${w.calendar.era||''}`:'';
const events=()=>w.entities.filter(e=>e.date).sort((a,b)=>dateOrdinal(a.date,w.calendar)-dateOrdinal(b.date,w.calendar));
const titleOf=r=>({home:'Overview',cards:'World entries',map:'Atlas',timeline:'Timeline',calendar:'Calendar',relations:'Relationships',tree:'Relation trees',canvas:'Canvas',wiki:'World wiki',settings:'World settings'}[r]);
let timelineZoom=1;
function timelineStrip(list){
 if(!list.length)return '';
 const yearDays=w.calendar.months.reduce((s,m)=>s+m.days,0),lo=dateOrdinal(list[0].date,w.calendar),hi=dateOrdinal(list.at(-1).date,w.calendar),span=Math.max(hi-lo,yearDays),width=1000*timelineZoom;
 const x=d=>70+(dateOrdinal(d,w.calendar)-lo)/span*(width-170);
 const ticks=Array.from({length:9},(_,i)=>{const ordinal=lo+span*i/8;return `<div class="timeline-tick" style="left:${70+i/8*(width-170)}px"><span>${Math.floor(ordinal/yearDays)} ${esc(w.calendar.era)}</span></div>`;}).join('');
 return `<div class="toolbar"><span class="hint">Visual chronology · scroll sideways to explore</span><span class="spacer"></span><button class="small" data-action="timeline-out" aria-label="Zoom out timeline">−</button><span class="hint">${timelineZoom}×</span><button class="small" data-action="timeline-in" aria-label="Zoom in timeline">+</button></div><div class="timeline-scroll"><div class="timeline-track" style="width:${width}px">${ticks}${list.map((e,i)=>`<button class="timeline-dot" data-open="${e.id}" style="left:${x(e.date)}px;top:${62+(i%3)*66}px"><span class="timeline-point"></span><strong>${esc(e.name)}</strong><small>${esc(dateText(e.date))}</small></button>`).join('')}</div></div>`;
}
function toast(t){const el=$('#toast');el.textContent=t;el.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.style.display='none',4000);}
function status(){const el=$('#save-state');if(el){el.textContent=saveError?'Save failed — export a backup':dirty||saving?'Saving to your computer…':editing?'Editing — use Save entry':'All changes saved locally';el.classList.toggle('error',!!saveError);el.title=saveError;}}
function change(force=false){dirty=true;checkpoint ||=force;generation++;saveError='';status();clearTimeout(saveTimer);saveTimer=setTimeout(save,350);}
async function save(){
 if(saving||!dirty)return;saving=true;dirty=false;const g=generation,cp=checkpoint;checkpoint=false;status();
 try{validateWorld(w);const r=await fetch('/api/world',{method:'PUT',headers:{'Content-Type':'application/json','X-Worldloom-Token':token},body:JSON.stringify({world:w,revision,checkpoint:cp})});const out=await r.json();if(!r.ok)throw Error(out.error);revision=out.revision;}
 catch(e){saveError=e.message;dirty=true;toast('Not saved: '+e.message);}
 finally{saving=false;status();if(dirty && !saveError && generation!==g)save();}
}
window.addEventListener('beforeunload',e=>{if(dirty||saving||editing){e.preventDefault();e.returnValue='';}});
function art(e){return `<div class="card-art" data-type="${esc(e.type)}">${e.image?`<img src="${esc(e.image)}" alt="${esc(e.name)}">`:`<span class="art-glyph">${glyph[e.type]||'✧'}</span>`}<span class="type-badge">${esc(e.type)}</span></div>`;}
function card(e){const links=w.relations.filter(r=>r.from===e.id||r.to===e.id).length;return `<button class="entity-card" data-open="${e.id}">${art(e)}<div class="card-info"><h3>${esc(e.name)}</h3><p>${esc(e.summary||'An unwritten piece of your world.')}</p></div><div class="card-footer"><span>${esc(e.tags[0]||e.type)}</span><span class="spacer"></span><span>${links} connection${links===1?'':'s'}</span></div></button>`;}
function markdown(s){
 const inline=t=>esc(t).replace(/\[\[([^\]]+)\]\]/g,(_,raw)=>{const name=raw.replace(/&amp;/g,'&').replace(/&#39;/g,"'").replace(/&quot;/g,'"').replace(/&lt;/g,'<').replace(/&gt;/g,'>');const e=w.entities.find(e=>e.name.toLowerCase()===name.toLowerCase());return e?`<a href="#" data-open="${e.id}">${raw}</a>`:`<span class="missing" title="No entry with this name">${raw}</span>`;}).replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/\*([^*]+)\*/g,'<em>$1</em>');
 return s.split(/\n\s*\n/).map(block=>{if(/^### /.test(block))return `<h3>${inline(block.slice(4))}</h3>`;if(/^##? /.test(block))return `<h2>${inline(block.replace(/^##? /,''))}</h2>`;return `<p>${inline(block)}</p>`;}).join('');
}
function shell(){
 app.innerHTML=`<aside class="sidebar"><div class="brand"><span class="brand-mark">✧</span><span>worldloom</span></div><button class="world-switch" data-route="settings"><span class="world-icon">${icon('leaf')}</span><span><strong>${esc(w.name)}</strong><small>Your local world</small></span></button><button class="nav-btn ${route==='home'?'active':''}" data-route="home">${icon('home')}<span>Overview</span></button><div class="nav-label">BUILD YOUR WORLD</div>${['cards','map','timeline','calendar','relations','tree','canvas'].map(r=>`<button class="nav-btn ${route===r?'active':''}" data-route="${r}">${icon(r)}<span>${titleOf(r)}</span>${r==='cards'?`<span class="count">${w.entities.length}</span>`:''}</button>`).join('')}<div class="nav-label">EXPLORE</div><button class="nav-btn ${route==='wiki'?'active':''}" data-route="wiki">${icon('wiki')}<span>World wiki</span></button><div class="sidebar-foot"><button class="nav-btn ${route==='settings'?'active':''}" data-route="settings">${icon('settings')}<span>World settings</span></button><div id="save-state" class="save-state"></div><button class="nav-btn" data-action="export">${icon('arrow')}<span>Export backup</span></button></div></aside><main class="workspace"><header class="topbar"><div class="breadcrumbs">${esc(w.name)}<span>/</span>${titleOf(route)}</div><div class="search">${icon('search')}<input id="search" aria-label="Search your world" placeholder="Search your world…"><span class="shortcut">Ctrl K</span></div><button class="primary small" data-action="new">+ New entry</button></header><div class="content" id="content"></div></main>`;
 $('#content').innerHTML=views[route]();bindView();status();$('#search').addEventListener('input',search);
}
function heading(title,subtitle,action=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${subtitle}</p></div>${action}</div>`;}
function empty(title,text,button=''){return `<div class="empty"><h2>${title}</h2><p>${text}</p>${button}</div>`;}
const views={
 home(){return `<section class="hero"><div class="hero-art"></div><div class="hero-copy"><span class="eyebrow">A WORLD WAITING TO UNFOLD</span><h1>${esc(w.name)}</h1><p>${esc(w.description||'Every character, every place, every thread. A world that belongs to you.')}</p><div class="row"><button class="primary" data-action="new">+ Create an entry</button><button class="outline-btn" data-route="wiki">Explore your world ${icon('arrow')}</button></div><div class="stats"><span><strong>${w.entities.length}</strong> entries</span><span><strong>${w.relations.length}</strong> connections</span><span><strong>${events().length}</strong> events</span></div></div></section><div class="section-heading"><h2>Ways into your world</h2><span class="local-badge">LOCAL · PRIVATE · YOURS</span></div><div class="tools-grid">${[['map','Explore the atlas','Places with a story'],['timeline','Follow the timeline','A history taking shape'],['relations','Trace connections','Everything is connected'],['canvas','Find your next idea','Space to think freely']].map(([r,t,s])=>`<button class="tool-tile" data-route="${r}">${icon(r)}<span><strong>${t}</strong><small>${s}</small></span></button>`).join('')}</div><div class="section-heading"><h2>The people, places & possibilities</h2><button class="ghost small" data-route="cards">View all entries →</button></div><div class="grid">${w.entities.slice(0,4).map(card).join('')||empty('Begin with a spark','Add a character, a place, or a question.',`<button data-action="new">Create your first entry</button>`)}</div><div class="bottom-grid"><div><div class="section-heading"><h2>Moments that shape your world</h2><button class="ghost small" data-route="timeline">Timeline →</button></div><div class="panel">${events().slice(-3).map(e=>`<div class="event-row"><div class="event-date">${e.date.year}<small>${esc(w.calendar.era)}</small></div><div><button data-open="${e.id}">${esc(e.name)}</button><p>${esc(e.summary)}</p></div></div>`).join('')||'<p class="muted">Your history starts with the first event.</p>'}</div></div><div><div class="section-heading"><h2>A place for every idea</h2></div><div class="panel"><span class="eyebrow">MAKE IT YOURS</span><h2 style="margin-top:12px">Follow a thread.</h2><p class="muted" style="font-size:12px">Write <strong>[[an entry name]]</strong> in your lore to link it. Connect creatures to habitats, factions to cities, and people to the events that changed them.</p><button class="ghost small" data-route="settings">Start your own world →</button></div></div></div>`;},
 cards(){const list=w.entities.filter(e=>filter==='All'||e.type===filter);const types=[...new Set([...TYPES,...w.entities.map(e=>e.type)])];return heading('Your world, in pieces.','Give every person, place, and possibility a home.')+`<div class="filters">${['All',...types].map(t=>`<button class="filter ${filter===t?'active':''}" data-filter="${esc(t)}">${esc(t)} <span class="muted">${w.entities.filter(e=>t==='All'||e.type===t).length}</span></button>`).join('')}</div><div class="grid">${list.map(card).join('')}</div>${list.length?'':empty('Room for something new',`Create your first ${esc(filter==='All'?'entry':filter.toLowerCase())}.`,`<button class="primary" data-action="new">+ New entry</button>`)}`;},
 map(){const m=currentMap();return heading('An atlas of possibility.','Every pin opens the same entry you use everywhere else.',`<button data-action="new-map">+ New map</button>`)+(!m?empty('Put your world on the map','Create a map, then add your own image.',`<button class="primary" data-action="new-map">Create map</button>`):`<div class="toolbar"><select id="map-select" aria-label="Map">${w.maps.map(x=>`<option value="${x.id}" ${x.id===m.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select><button data-action="map-image">Upload map image</button><button class="${mapMode==='pin'?'primary':''}" data-action="map-pin">${mapMode==='pin'?'Cancel pin':'＋ Place pin'}</button><button class="${mapMode==='region'?'primary':''}" data-action="map-region">${mapMode==='region'?'Cancel region':'◇ Draw region'}</button>${mapMode==='region'?'<button data-action="finish-region">Finish region</button>':''}<span class="spacer"></span><button class="small ghost" data-action="manage-map">Manage</button></div><div class="view-stage map-stage" id="map-stage"><img src="${esc(m.image||'/landscape.svg')}" alt="${esc(m.name)}"><svg class="map-overlay" viewBox="0 0 100 100" preserveAspectRatio="none">${m.regions.map((r,i)=>`<polygon class="map-region" points="${r.points.map(p=>`${p.x},${p.y}`).join(' ')}" data-region="${i}"><title>${esc(r.name)}</title></polygon>`).join('')}${pendingPoints.length?`<polyline points="${pendingPoints.map(p=>`${p.x},${p.y}`).join(' ')}" fill="#c4bd7030" stroke="#ead395" stroke-width=".25"/>`:''}</svg>${m.pins.map(p=>{const e=entity(p.entity);return `<button class="pin" style="left:${p.x}%;top:${p.y}%" data-pin="${p.id}" title="${esc(e?.name)} — drag to move"><span>✦</span></button><span class="pin-label" style="left:${p.x}%;top:${p.y}%">${esc(e?.name)}</span>`;}).join('')}<div class="map-help">${mapMode==='pin'?'Click the map to place a linked pin.':mapMode==='region'?'Click to add boundary points, then choose Finish region.':'Click a pin to open its entry. Drag pins to move them.'}</div></div>`);},
 timeline(){const list=events();return heading('A history taking shape.','Events follow your world’s calendar. Open any moment to explore its story.',`<button class="primary" data-action="new-event">+ Add event</button>`)+`<div class="toolbar"><span class="pill">${esc(w.calendar.era||'World calendar')}</span><span class="muted" style="font-size:11px">${list.length} dated entries · chronological order</span><span class="spacer"></span><button class="small" data-action="calendar-settings">Edit calendar</button></div>`+(list.length?timelineStrip(list)+`<div class="timeline-list">${list.map(e=>`<article class="time-card"><span class="date">${esc(dateText(e.date))}</span><h2>${esc(e.name)}</h2><p>${esc(e.summary)}</p><div class="row">${e.tags.map(t=>`<span class="pill">${esc(t)}</span>`).join('')}<span class="spacer"></span><button class="ghost small" data-open="${e.id}">Open entry →</button></div></article>`).join('')}</div>`:empty('Every world has a beginning','Create an event to begin your history.'));},
 calendar(){const c=w.calendar,month=c.months[calendarMonth];const start=((dateOrdinal({year:calendarYear,month:calendarMonth,day:1},c)%c.weekdays.length)+c.weekdays.length)%c.weekdays.length;return heading('Time, on your terms.','A calendar made for the world you imagine.',`<button data-action="calendar-settings">Customize calendar</button>`)+`<div class="toolbar"><button data-action="prev-month" aria-label="Previous month">←</button><select id="month-select" aria-label="Month">${c.months.map((m,i)=>`<option value="${i}" ${i===calendarMonth?'selected':''}>${esc(m.name)}</option>`).join('')}</select><input id="year-input" type="number" min="-1000000" max="1000000" value="${calendarYear}" style="width:105px" aria-label="Year"><span class="muted">${esc(c.era)}</span><button data-action="next-month" aria-label="Next month">→</button><span class="spacer"></span><span class="hint">Click a day to add an event</span></div><div class="calendar" style="grid-template-columns:repeat(${c.weekdays.length},1fr)">${c.weekdays.map(d=>`<div class="weekday">${esc(d)}</div>`).join('')}${Array.from({length:start},()=>'<div class="day blank"></div>').join('')}${Array.from({length:month.days},(_,i)=>`<div class="day" data-day="${i+1}"><button class="day-number" data-day="${i+1}" aria-label="Add event on ${i+1} ${esc(month.name)}">${i+1}</button>${events().filter(e=>e.date.year===calendarYear&&e.date.month===calendarMonth&&e.date.day===i+1).map(e=>`<button class="calendar-event" data-open="${e.id}">${esc(e.name)}</button>`).join('')}</div>`).join('')}</div>`;},
 relations(){return graphView(false);},tree(){return graphView(true);},
 canvas(){const b=currentBoard();return heading('Space to follow an idea.','Arrange linked entries and notes. Drag a card by its top bar.',`<button data-action="new-board">+ New canvas</button>`)+(!b?empty('A blank canvas awaits','Create a board to connect your ideas.',`<button data-action="new-board">New canvas</button>`):`<div class="toolbar"><select id="board-select" aria-label="Canvas">${w.boards.map(x=>`<option value="${x.id}" ${x.id===b.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select><button data-action="canvas-entry">+ Add entry</button><button data-action="canvas-note">+ Add note</button><button data-action="new-relation">Connect entries</button><span class="spacer"></span><button class="ghost small" data-action="rename-board">Rename</button></div><div class="view-stage board-stage"><div class="board-space" id="board-space"><svg class="board-lines">${boardLines(b)}</svg>${b.nodes.map(n=>{const e=entity(n.entity);return `<div class="board-card" data-node="${n.id}" style="left:${n.x}px;top:${n.y}px"><div class="board-handle" data-drag-node="${n.id}"><span>⠿ ${e?esc(e.type):'THOUGHT'}</span><button data-remove-node="${n.id}" aria-label="Remove from canvas">×</button></div><div class="board-card-body" ${e?`data-open="${e.id}"`:`data-edit-note="${n.id}"`}>${e?`<h3>${esc(e.name)}</h3><p>${esc(e.summary)}</p>`:`<p class="board-note">${esc(n.text)}</p>`}</div></div>`;}).join('')}</div></div>`);},
 wiki(){const e=entity(wikiId)||w.entities[0];return heading('The world, as a story.','A reader’s view of your living encyclopedia.',`<button data-action="export-wiki">Export wiki HTML</button>`)+`<div class="wiki-layout"><aside class="wiki-index">${[...new Set(w.entities.map(e=>e.type))].map(type=>`<div class="nav-label">${esc(type)}</div>${w.entities.filter(e=>e.type===type).map(x=>`<button data-wiki="${x.id}" class="${e?.id===x.id?'active':''}">${esc(x.name)}</button>`).join('')}`).join('')}</aside><article class="wiki-page">${e?`<span class="eyebrow">${esc(e.type)}</span><h1>${esc(e.name)}</h1><p class="muted">${esc(e.summary)}</p>${props(e)}<div class="prose">${markdown(e.body)}</div>${related(e)}<button class="ghost small" data-open="${e.id}">Edit this entry →</button>`:empty('Your encyclopedia starts here','Create your first entry and it will appear in the wiki.')}</article></div>`;},
 settings(){return heading('A world of your own.','Your files stay on this computer. No account. No subscription.')+`<div class="settings-grid"><section class="panel"><h2>World details</h2><form id="world-form" class="stack"><label>Name<input name="name" value="${esc(w.name)}" required maxlength="200"></label><label>A sentence about your world<textarea name="description" rows="3">${esc(w.description)}</textarea></label><button class="primary" type="submit">Save details</button></form></section><section class="panel"><h2>Your calendar</h2><p>${w.calendar.months.length} months · ${w.calendar.weekdays.length}-day weeks · ${w.calendar.months.reduce((s,m)=>s+m.days,0)} days per year</p><p>Months and weekdays are yours to name. Dates connect the calendar, timeline, and event entries.</p><button data-action="calendar-settings">Customize calendar</button><p class="hint" style="margin-top:15px">This version uses a repeating year. Leap rules, moon cycles, and multiple calendar systems are not yet included.</p></section><section class="panel"><h2>Keep a copy</h2><p>The app saves into the <strong>world</strong> folder beside its files. It keeps up to 40 automatic snapshots. Export a full backup to move your world to another computer.</p><div class="settings-actions"><button data-action="export">Export full backup</button><button data-action="import">Import backup</button><button data-action="export-markdown">Export Markdown</button><button data-action="export-wiki">Export wiki HTML</button></div><p class="hint" style="margin-top:15px">JSON backups preserve every map, canvas, image, relationship, and calendar. Markdown and HTML exports are readable copies of your entries.</p></section><section class="panel"><h2>Recover a previous version</h2><p>Restoring creates a snapshot of your current world first.</p><button data-action="backups">Show saved versions</button><div class="backup-list" id="backups" style="margin-top:15px"></div></section><section class="panel"><h2>Begin a new world</h2><p>The Waking Coast is an editable example. Start with a blank world when you’re ready. Your current world is backed up first.</p><button data-action="blank-world">Create a blank world</button><p class="hint" style="margin-top:15px">One active world in this version. Export backups to keep separate worlds.</p></section><section class="panel"><h2>Make connections</h2><p>Use <strong>[[Entry name]]</strong> in the editor to link lore. Add named relationships to connect cards across your graphs and canvases. Mark a relationship as “Family / tree” to include it in relation trees.</p><div class="help-box">Keyboard: Ctrl K to search · Escape to close an entry<br>Import images from your computer. No remote fonts, tracking, or network services are used.</div></section></div>`;}
};
function props(e){return `<div class="properties">${e.date?`<div class="property"><span>Date</span><div>${esc(dateText(e.date))}</div></div>`:''}${e.properties.map(p=>`<div class="property"><span>${esc(p.key)}</span><div>${esc(p.value)}</div></div>`).join('')}</div>`;}
function related(e){const rs=w.relations.filter(r=>r.from===e.id||r.to===e.id);const backlinks=w.entities.filter(x=>x.id!==e.id&&x.body.toLowerCase().includes(`[[${e.name.toLowerCase()}]]`));return `<div class="section-heading"><h2>Connections</h2><button class="ghost small" data-action="new-relation">+ Connect</button></div><div class="relation-list">${rs.map(r=>`<div class="relation-item"><span>${r.from===e.id?esc(r.label):`← ${esc(r.label)}`}</span><button data-open="${r.from===e.id?r.to:r.from}">${esc(entity(r.from===e.id?r.to:r.from)?.name)}</button><span class="spacer"></span><button data-delete-relation="${r.id}" aria-label="Remove relationship">×</button></div>`).join('')||'<p class="hint">No named connections yet.</p>'}</div>${backlinks.length?`<div class="section-heading"><h2>Mentioned in</h2></div><div class="relation-list">${backlinks.map(x=>`<button class="small" data-open="${x.id}">${esc(x.name)}</button>`).join('')}</div>`:''}`;}
function graphView(tree){
 const rs=w.relations.filter(r=>!tree||r.kind==='family');const ids=new Set(rs.flatMap(r=>[r.from,r.to]));const nodes=tree?w.entities.filter(e=>ids.has(e.id)):w.entities;
 const pos={};nodes.forEach((e,i)=>{const a=(i/Math.max(nodes.length,1))*Math.PI*2-Math.PI/2;pos[e.id]={x:500+Math.cos(a)*Math.min(350,90+nodes.length*25),y:290+Math.sin(a)*Math.min(220,70+nodes.length*18)};});
 if(tree){const levels=treeLevels(nodes,rs),max=Math.max(1,...levels.values());for(let level=0;level<=max;level++){const group=nodes.filter(e=>levels.get(e.id)===level);group.forEach((e,i)=>{pos[e.id]={x:100+(i+1)*800/(group.length+1),y:80+level*400/max};});}}
 return heading(tree?'The ties that shape a life.':'Nothing exists alone.',tree?'Family and tree connections, backed by the same world entries.':'Named relationships across your world. Click any node to explore.',`<button class="primary" data-action="${tree?'new-family':'new-relation'}">+ Add relationship</button>`)+(!nodes.length?empty(tree?'Start with a connection':'A world waiting to connect',tree?'Choose two entries and give their relationship a name.':'Create entries, then connect them.'):`<div class="toolbar"><span class="pill">${nodes.length} entries</span><span class="pill">${rs.length} relationships</span><span class="hint">Arrows run from source to target · ${tree?'Family / tree relationships only':'Named relationships only; text mentions appear as backlinks'}</span></div><div class="view-stage graph-stage"><svg viewBox="0 0 1000 580" role="img" aria-label="Interactive relationship graph"><defs><marker id="arrowhead" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0 0 10 5 0 10" fill="#839f8c"/></marker></defs>${rs.map(r=>{const a=pos[r.from],b=pos[r.to];if(!a||!b)return '';const dx=b.x-a.x,dy=b.y-a.y,len=Math.hypot(dx,dy)||1;return `<line class="graph-edge" x1="${a.x+dx/len*32}" y1="${a.y+dy/len*32}" x2="${b.x-dx/len*35}" y2="${b.y-dy/len*35}" marker-end="url(#arrowhead)"/><text class="graph-label" x="${(a.x+b.x)/2}" y="${(a.y+b.y)/2-5}" text-anchor="middle">${esc(r.label)}</text>`;}).join('')}${nodes.map(e=>`<g class="graph-node" data-open="${e.id}" tabindex="0" role="button" aria-label="Open ${esc(e.name)}" transform="translate(${pos[e.id].x},${pos[e.id].y})"><circle r="31" fill="${e.type==='Character'?'#514d41':e.type==='Location'?'#354e49':'#36433b'}"/><text text-anchor="middle" y="9" style="font-size:27px;fill:#d7c69d">${glyph[e.type]||'✧'}</text><text text-anchor="middle" y="51">${esc(e.name)}</text><text text-anchor="middle" y="67" style="font-size:9px;fill:#809185">${esc(e.type)}</text></g>`).join('')}</svg></div>`);
}
function boardLines(b){return w.relations.map(r=>{const a=b.nodes.find(n=>n.entity===r.from),z=b.nodes.find(n=>n.entity===r.to);if(!a||!z)return '';return `<line x1="${a.x+115}" y1="${a.y+70}" x2="${z.x+115}" y2="${z.y+70}" stroke="#c1b38470" stroke-width="2"/><text x="${(a.x+z.x)/2+115}" y="${(a.y+z.y)/2+65}" class="graph-label" text-anchor="middle">${esc(r.label)}</text>`;}).join('');}
function navigate(r){if(!leaveEditor())return;route=r;mapMode='';pendingPoints=[];shell();}
function leaveEditor(){if(editing){if(!confirm('Discard the changes in this entry editor?'))return false;editing=false;showInspector();}return true;}
function openEntry(id){if(!leaveEditor())return;selected=id;showInspector();}
function closeEntry(){if(!leaveEditor())return;selected='';inspector.innerHTML='';document.body.classList.remove('inspector-open');}
function showInspector(){status();const e=entity(selected);if(!e){selected='';inspector.innerHTML='';document.body.classList.remove('inspector-open');return;}document.body.classList.add('inspector-open');inspector.innerHTML=`<aside class="inspector"><div class="inspector-head"><span class="eyebrow">${editing?'EDIT ENTRY':esc(e.type)}</span><div class="row">${editing?'':`<button class="small" data-action="edit-entry">Edit</button>`}<button class="ghost small" data-action="close-entry" aria-label="Close entry">${icon('close')}</button></div></div>${editing?editMarkup(e):`${art(e)}<div class="inspector-body"><h1>${esc(e.name)}</h1><p class="summary">${esc(e.summary)}</p><div class="row" style="flex-wrap:wrap">${e.tags.map(t=>`<span class="pill">${esc(t)}</span>`).join('')}</div>${props(e)}<div class="prose">${markdown(e.body)}</div>${related(e)}<div class="section-heading"><button class="ghost small" data-action="entry-to-canvas">Add to canvas</button><button class="ghost small danger" data-action="delete-entry">Delete entry</button></div></div>`}</aside>`;if(editing)bindEditor(e);}
function editMarkup(e){return `<form id="entry-form" class="inspector-body edit-form"><label>Name<input name="name" value="${esc(e.name)}" required maxlength="200"></label><label>Type<input name="type" value="${esc(e.type)}" list="types" required maxlength="60"><datalist id="types">${TYPES.map(t=>`<option>${t}</option>`).join('')}</datalist></label><label>In one sentence<textarea name="summary" rows="2">${esc(e.summary)}</textarea></label><label>Tags, separated by commas<input name="tags" value="${esc(e.tags.join(', '))}"></label><div class="row"><button type="button" data-action="entry-image">Choose image</button><button type="button" data-action="clear-image" class="ghost small">Remove image</button><span class="hint" id="image-status">${e.image?'Image attached':'Optional'}</span></div>${e.type==='Event'||e.date?dateFields(e.date||{year:calendarYear,month:calendarMonth,day:1}):''}<label>Lore<textarea class="body-edit" name="body" placeholder="Tell its story. Link another entry with [[Entry name]].">${esc(e.body)}</textarea></label><div class="hint">Use ## for headings, **bold**, *italic*, and [[Entry name]] for links.</div><div><div class="row spread"><span class="muted" style="font-size:12px">Custom fields</span><button type="button" class="small ghost" data-action="add-property">+ Add field</button></div><div id="prop-fields" class="stack" style="gap:7px;margin-top:10px">${e.properties.map(p=>propertyInput(p)).join('')}</div></div><div class="error-text" id="editor-error"></div><div class="row"><button type="submit" class="primary">Save entry</button><button type="button" data-action="cancel-edit">Cancel</button></div></form>`;}
function propertyInput(p={key:'',value:''}){return `<div class="prop-edit"><input aria-label="Field name" class="prop-key" value="${esc(p.key)}" placeholder="Field"><input aria-label="Field value" class="prop-value" value="${esc(p.value)}" placeholder="Value"><button type="button" data-action="remove-property" aria-label="Remove field">×</button></div>`;}
function dateFields(d){return `<div class="date-fields"><label>Year<input type="number" name="year" value="${d.year}" min="-1000000" max="1000000" required></label><label>Month<select name="month">${w.calendar.months.map((m,i)=>`<option value="${i}" ${i===d.month?'selected':''}>${esc(m.name)}</option>`).join('')}</select></label><label>Day<input type="number" name="day" min="1" max="100" value="${d.day}" required></label></div>`;}
let draftImage='';
function bindEditor(e){draftImage=e.image;$('#entry-form').onsubmit=ev=>{ev.preventDefault();const f=new FormData(ev.currentTarget);const name=f.get('name').trim();if(w.entities.some(x=>x.id!==e.id&&x.name.toLowerCase()===name.toLowerCase())){$('#editor-error').textContent='An entry already has this name.';return;}const date=f.has('year')?{year:Number(f.get('year')),month:Number(f.get('month')),day:Number(f.get('day'))}:undefined;try{if(date)dateOrdinal(date,w.calendar);}catch(err){$('#editor-error').textContent=err.message;return;}const old=e.name;Object.assign(e,{name,type:f.get('type').trim(),summary:f.get('summary'),body:f.get('body'),tags:f.get('tags').split(',').map(t=>t.trim()).filter(Boolean),image:draftImage,properties:$$('.prop-edit').map(el=>({key:$('.prop-key',el).value.trim(),value:$('.prop-value',el).value})).filter(p=>p.key),updated:Date.now()});if(date)e.date=date;
 if(name!==old){const re=new RegExp('\\[\\['+old.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'\\]\\]','gi');w.entities.forEach(x=>x.body=x.body.replace(re,()=>`[[${name}]]`));}
 editing=false;change();shell();showInspector();toast('Entry saved.');};}
function modal(title,description,fields,onSubmit,submit='Create'){
 dialog.innerHTML=`<button class="dialog-close" aria-label="Close dialog" data-action="close-dialog">${icon('close')}</button><h2>${title}</h2><p>${description}</p><form id="modal-form">${fields}<div class="error-text" id="modal-error"></div><div class="dialog-actions"><button type="button" data-action="close-dialog">Cancel</button><button type="submit" class="primary">${submit}</button></div></form>`;dialog.showModal();$('#modal-form').onsubmit=async ev=>{ev.preventDefault();try{await onSubmit(new FormData(ev.currentTarget));}catch(e){$('#modal-error').textContent=e.message;}};
}
function options(chosen=''){return w.entities.map(e=>`<option value="${e.id}" ${e.id===chosen?'selected':''}>${esc(e.name)} · ${esc(e.type)}</option>`).join('');}
function createEntry(type=filter!=='All'?filter:'Character',date){
 if(!leaveEditor())return;modal('A new piece of your world.','Start with a name. The story can come later.',`<label>Name<input name="name" required autofocus maxlength="200" placeholder="What is it called?"></label><label>Type<select name="type">${[...new Set([...TYPES,...w.entities.map(e=>e.type),type])].map(t=>`<option ${t===type?'selected':''}>${esc(t)}</option>`).join('')}</select></label><label>In one sentence<textarea name="summary" rows="2" placeholder="A detail that makes it yours…"></textarea></label>${date?dateFields(date):''}`,f=>{const name=f.get('name').trim();if(!name)throw Error('Give this entry a name.');if(w.entities.some(e=>e.name.toLowerCase()===name.toLowerCase()))throw Error('An entry already has this name.');const e={id:uid(),name,type:f.get('type'),summary:f.get('summary'),body:'',tags:[],properties:[],image:'',updated:Date.now()};if(date||e.type==='Event'){e.date=date?{year:Number(f.get('year')),month:Number(f.get('month')),day:Number(f.get('day'))}:{year:calendarYear,month:calendarMonth,day:1};dateOrdinal(e.date,w.calendar);}w.entities.push(e);dialog.close();change();shell();selected=e.id;editing=true;showInspector();},'Create entry');
}
function newRelation(kind='connection'){
 if(w.entities.length<2){toast('Create at least two entries to connect.');return;}modal('Connect two pieces.','The same relationship appears in entry pages, graphs, and canvases.',`<label>From<select name="from">${options(selected)}</select></label><label>Relationship<input name="label" placeholder="e.g. leads, inhabits, parent of" required maxlength="100"></label><label>To<select name="to">${options(w.entities.find(e=>e.id!==selected)?.id)}</select></label><label>Show in<select name="kind"><option value="connection" ${kind==='connection'?'selected':''}>Relationships</option><option value="family" ${kind==='family'?'selected':''}>Relationships + family / tree</option></select></label>`,f=>{if(f.get('from')===f.get('to'))throw Error('Choose two different entries.');if(!f.get('label').trim())throw Error('Name the relationship.');w.relations.push({id:uid(),from:f.get('from'),to:f.get('to'),label:f.get('label').trim(),kind:f.get('kind')});dialog.close();change();shell();showInspector();},'Connect');
}
function filePick(accept,fn){const input=document.createElement('input');input.type='file';input.accept=accept;input.onchange=()=>{if(input.files[0])Promise.resolve(fn(input.files[0])).catch(e=>toast(e.message));};input.click();}
async function readImage(file){if(!['image/png','image/jpeg','image/webp','image/gif'].includes(file.type))throw Error('Choose a PNG, JPG, WebP, or GIF image.');if(file.size>6*1024*1024)throw Error('Please choose an image smaller than 6 MB.');return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('Could not read image.'));r.readAsDataURL(file);});}
function download(name,text,type='application/json'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function slug(s){return s.replace(/[^a-zA-Z0-9_-]/g,'-').replace(/-+/g,'-').slice(0,80)||'world';}
function exportWorld(){download(slug(w.name)+'.worldloom.json',JSON.stringify(w,null,2));toast('Full world backup exported.');}
function exportMarkdown(){download(slug(w.name)+'.md',`# ${w.name}\n\n${w.description}\n\n`+w.entities.map(e=>`# ${e.name}\n\nType: ${e.type}\n\n${e.summary}\n\n${e.date?'Date: '+dateText(e.date)+'\n\n':''}${e.properties.map(p=>`- ${p.key}: ${p.value}`).join('\n')}\n\n${e.body}\n\n## Connections\n\n${w.relations.filter(r=>r.from===e.id).map(r=>`- ${r.label}: [[${entity(r.to)?.name}]]`).join('\n')}`).join('\n\n---\n\n'),'text/markdown');}
function exportWiki(){const html=`<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(w.name)}</title><style>body{background:#171e1c;color:#dbe2d7;font:16px/1.8 Georgia,serif;max-width:850px;margin:50px auto;padding:25px}a{color:#d5bf8d}article{padding:40px 0;border-bottom:1px solid #ffffff22}img{max-width:100%;max-height:350px}h1,h2{font-weight:400}.muted{color:#9da996}.property{display:flex;gap:20px}.property span{color:#9da996}.prose p{white-space:pre-wrap}</style><h1>${esc(w.name)}</h1><p>${esc(w.description)}</p><nav>${w.entities.map(e=>`<a href="#${e.id}">${esc(e.name)}</a>`).join(' · ')}</nav>${w.entities.map(e=>`<article id="${e.id}"><small>${esc(e.type)}</small><h1>${esc(e.name)}</h1>${e.image?`<img src="${e.image}" alt="${esc(e.name)}">`:''}<p class="muted">${esc(e.summary)}</p>${props(e)}<div class="prose">${markdown(e.body).replace(/href="#" data-open="([^"]+)"/g,'href="#$1"')}</div><p>${w.relations.filter(r=>r.from===e.id).map(r=>`${esc(r.label)}: <a href="#${r.to}">${esc(entity(r.to)?.name)}</a>`).join(' · ')}</p></article>`).join('')}</html>`;download(slug(w.name)+'-wiki.html',html,'text/html');toast('A standalone, offline wiki exported.');}
function calendarSettings(){const c=w.calendar;modal('Give time its own rhythm.','Changing the calendar will validate every existing event before saving.',`<label>Era suffix<input name="era" value="${esc(c.era)}" placeholder="e.g. AT"></label><label>Weekdays, separated by commas<input name="weekdays" value="${esc(c.weekdays.join(', '))}" required></label><div class="row spread"><span class="muted">Months</span><button type="button" data-action="add-month" class="small">+ Month</button></div><div class="calendar-months" id="calendar-months">${c.months.map(monthInput).join('')}</div><p class="hint">Month order is significant. Existing event dates keep their month position. Reordering or removing months can change their meaning.</p>`,f=>{const next={...c,era:f.get('era'),weekdays:f.get('weekdays').split(',').map(s=>s.trim()).filter(Boolean),months:$$('.calendar-month',dialog).map(el=>({name:$('.month-name',el).value.trim(),days:Number($('.month-days',el).value)}))};const proposed={...w,calendar:next};validateWorld(proposed);w.calendar=next;calendarMonth=Math.min(calendarMonth,next.months.length-1);dialog.close();change(true);shell();showInspector();},'Save calendar');}
function monthInput(m){return `<div class="calendar-month"><input class="month-name" value="${esc(m.name)}" aria-label="Month name" required><input class="month-days" type="number" min="1" max="100" value="${m.days}" aria-label="Days in month" required><button type="button" data-action="remove-month" aria-label="Remove month">×</button></div>`;}
function addCanvasEntry(id=''){
 const b=currentBoard();if(!b){toast('Create a canvas first.');return;}if(!w.entities.length){toast('Create an entry first.');return;}
 modal('Bring an entry onto the canvas.','This card stays connected to its original entry.',`<label>Entry<select name="entry">${options(id)}</select></label>`,f=>{b.nodes.push({id:uid(),entity:f.get('entry'),x:70+(b.nodes.length%4)*280,y:70+Math.floor(b.nodes.length/4)*230});dialog.close();change();shell();},'Add entry');
}
function noteModal(node){modal(node?'Edit a thought.':'Leave a thought.','Notes belong to this canvas. Use an entry for lore you want to reuse.',`<label>Note<textarea name="text" rows="6" required>${esc(node?.text||'')}</textarea></label>`,f=>{if(node)node.text=f.get('text');else currentBoard().nodes.push({id:uid(),text:f.get('text'),x:130,y:100});dialog.close();change();shell();},node?'Save note':'Add note');}
const actions={
 'timeline-in':()=>{timelineZoom=Math.min(8,timelineZoom*2);shell();},'timeline-out':()=>{timelineZoom=Math.max(1,timelineZoom/2);shell();},
 new:()=>createEntry(), 'new-event':()=>createEntry('Event',{year:calendarYear,month:calendarMonth,day:1}), 'close-entry':closeEntry,
 'edit-entry':()=>{editing=true;showInspector();},'cancel-edit':()=>{editing=false;showInspector();},'close-dialog':()=>dialog.close(),
 'new-relation':()=>newRelation(),'new-family':()=>newRelation('family'),export:exportWorld,'export-markdown':exportMarkdown,'export-wiki':exportWiki,
 'calendar-settings':calendarSettings,'add-month':()=>$('#calendar-months').insertAdjacentHTML('beforeend',monthInput({name:'New month',days:30})),
 'remove-month':el=>el.closest('.calendar-month').remove(),'add-property':()=>$('#prop-fields').insertAdjacentHTML('beforeend',propertyInput()),'remove-property':el=>el.closest('.prop-edit').remove(),
 'entry-image':()=>filePick('image/png,image/jpeg,image/webp,image/gif',async f=>{draftImage=await readImage(f);$('#image-status').textContent='New image ready — save entry to apply';}),
 'clear-image':()=>{draftImage='';$('#image-status').textContent='Image removed — save entry to apply';},
 'delete-entry':()=>{const e=entity(selected);if(confirm(`Delete “${e.name}”? Its relationships, map pins, and canvas cards will also be removed. A backup will be kept.`)){removeEntity(w,e.id);selected='';change(true);shell();showInspector();}},
 'new-map':()=>modal('A new perspective.','Create an atlas view, then upload a map image.',`<label>Name<input name="name" required placeholder="The northern kingdoms"></label>`,f=>{if(!f.get('name').trim())throw Error('Enter a name.');const m={id:uid(),name:f.get('name').trim(),image:'',pins:[],regions:[]};w.maps.push(m);mapId=m.id;dialog.close();change();shell();},'Create map'),
 'map-image':()=>filePick('image/png,image/jpeg,image/webp,image/gif',async f=>{currentMap().image=await readImage(f);change();shell();}),
 'map-pin':()=>{mapMode=mapMode==='pin'?'':'pin';pendingPoints=[];shell();},'map-region':()=>{mapMode=mapMode==='region'?'':'region';pendingPoints=[];shell();},
 'finish-region':()=>{if(pendingPoints.length<3){toast('Add at least three boundary points.');return;}modal('Name this region.','Optionally connect it to a world entry.',`<label>Region name<input name="name" required></label><label>Linked entry<select name="entity"><option value="">No linked entry</option>${options()}</select></label>`,f=>{currentMap().regions.push({name:f.get('name'),entity:f.get('entity'),points:[...pendingPoints]});pendingPoints=[];mapMode='';dialog.close();change();shell();},'Save region');},
 'manage-map':()=>{const m=currentMap();modal('Map details.','Remove individual markers or rename this map.',`<label>Name<input name="name" required value="${esc(m.name)}"></label><div class="stack">${m.pins.map(p=>`<div class="row spread"><span>${esc(entity(p.entity)?.name)}</span><button type="button" class="small danger" data-remove-pin="${p.id}">Remove pin</button></div>`).join('')}${m.regions.map((r,i)=>`<div class="row spread"><span>${esc(r.name)}</span><button type="button" class="small danger" data-remove-region="${i}">Remove region</button></div>`).join('')}</div>`,f=>{m.name=f.get('name').trim();if(!m.name)throw Error('Enter a name.');dialog.close();change();shell();},'Save name');},
 'prev-month':()=>stepMonth(-1),'next-month':()=>stepMonth(1),
 'new-board':()=>modal('Make room for ideas.','A canvas for connections, loose thoughts, and possibilities.',`<label>Name<input name="name" required placeholder="The first chapter"></label>`,f=>{if(!f.get('name').trim())throw Error('Enter a name.');const b={id:uid(),name:f.get('name').trim(),nodes:[]};w.boards.push(b);boardId=b.id;dialog.close();change();shell();},'Create canvas'),
 'rename-board':()=>modal('Rename canvas.','',`<label>Name<input name="name" required value="${esc(currentBoard().name)}"></label>`,f=>{if(!f.get('name').trim())throw Error('Enter a name.');currentBoard().name=f.get('name').trim();dialog.close();change();shell();},'Rename'),
 'canvas-entry':()=>addCanvasEntry(),'entry-to-canvas':()=>{route='canvas';shell();addCanvasEntry(selected);},'canvas-note':()=>noteModal(),
 import:()=>filePick('.json',async f=>{if(f.size>48*1024*1024)throw Error('Backup is too large.');const next=validateWorld(JSON.parse(await f.text()));if(confirm(`Replace the active world with “${next.name}”? The current saved world will be backed up.`)){await replaceWorld(next);}}),
 backups:async()=>{const r=await fetch('/api/backups');const {files}=await r.json();$('#backups').innerHTML=files.length?files.map(f=>`<button data-restore="${esc(f)}">${esc(f.replace('.json',''))} ↶</button>`).join(''):'<p class="hint">No snapshots yet. A backup is created when you first save.</p>';},
 'blank-world':()=>modal('Your next world begins here.','Your current saved world will be backed up before it is replaced.',`<label>World name<input name="name" required placeholder="An unwritten world"></label><label>A sentence about it<textarea name="description" rows="3"></textarea></label>`,async f=>{const next={format:'worldloom',version:1,name:f.get('name').trim(),description:f.get('description'),calendar:structuredClone(w.calendar),entities:[],relations:[],maps:[],boards:[]};validateWorld(next);await replaceWorld(next);dialog.close();},'Start world')
};
async function replaceWorld(next){if(saving){throw Error('Please wait for the current save to finish.');}if(dirty){await save();if(saveError)throw Error('Export your current work before replacing it: '+saveError);}w=next;selected='';editing=false;mapId='';boardId='';wikiId='';calendarMonth=0;calendarYear=w.calendar.currentYear||0;filter='All';change(true);await save();route='home';shell();showInspector();if(!saveError)toast('World opened.');}
function stepMonth(delta){calendarMonth+=delta;if(calendarMonth<0){calendarMonth=w.calendar.months.length-1;calendarYear--;}if(calendarMonth>=w.calendar.months.length){calendarMonth=0;calendarYear++;}shell();}
function search(){const q=$('#search').value.toLowerCase().trim();$('#search-results')?.remove();if(!q)return;const list=w.entities.filter(e=>(e.name+' '+e.type+' '+e.summary+' '+e.tags.join(' ')+' '+e.body).toLowerCase().includes(q)).slice(0,20);const div=document.createElement('div');div.id='search-results';div.className='search-results';div.innerHTML=list.map(e=>`<button data-open="${e.id}">${esc(e.name)}<small>${esc(e.type)}</small></button>`).join('')||'<p class="hint" style="padding:10px">No entries found.</p>';document.body.append(div);}
document.addEventListener('click',async ev=>{
 const el=ev.target.closest('[data-action],[data-route],[data-open],[data-filter],[data-wiki],[data-day],[data-region],[data-remove-node],[data-edit-note],[data-delete-relation],[data-remove-pin],[data-remove-region],[data-restore]');
 if(!el){if(!ev.target.closest('.search'))$('#search-results')?.remove();return;}
 try{
  if(el.dataset.open){ev.preventDefault();$('#search-results')?.remove();openEntry(el.dataset.open);return;}
  if(el.dataset.route){navigate(el.dataset.route);return;}
  if(el.dataset.action){await actions[el.dataset.action]?.(el);return;}
  if(el.dataset.filter){filter=el.dataset.filter;shell();return;}
  if(el.dataset.wiki){wikiId=el.dataset.wiki;shell();return;}
  if(el.dataset.day){createEntry('Event',{year:calendarYear,month:calendarMonth,day:Number(el.dataset.day)});return;}
  if(el.dataset.region!==undefined && !mapMode){const r=currentMap().regions[Number(el.dataset.region)];if(r.entity)openEntry(r.entity);else toast(r.name);return;}
  if(el.dataset.removeNode){currentBoard().nodes=currentBoard().nodes.filter(n=>n.id!==el.dataset.removeNode);change();shell();return;}
  if(el.dataset.editNote){noteModal(currentBoard().nodes.find(n=>n.id===el.dataset.editNote));return;}
  if(el.dataset.deleteRelation){if(confirm('Remove this relationship?')){w.relations=w.relations.filter(r=>r.id!==el.dataset.deleteRelation);change();shell();showInspector();}return;}
  if(el.dataset.removePin){currentMap().pins=currentMap().pins.filter(p=>p.id!==el.dataset.removePin);el.closest('.row').remove();change();shell();return;}
  if(el.dataset.removeRegion!==undefined){currentMap().regions.splice(Number(el.dataset.removeRegion),1);dialog.close();change();shell();return;}
  if(el.dataset.restore){if(confirm('Restore this saved version? Your current world will be backed up first.')){const r=await fetch('/api/backup/'+encodeURIComponent(el.dataset.restore));if(!r.ok)throw Error('Could not load backup.');await replaceWorld(validateWorld(await r.json()));}}
 }catch(e){toast(e.message);}
});
document.addEventListener('keydown',ev=>{if((ev.ctrlKey||ev.metaKey)&&ev.key.toLowerCase()==='k'){ev.preventDefault();$('#search').focus();}if(ev.key==='Escape'&&!dialog.open){$('#search-results')?.remove();closeEntry();}if(ev.key==='Enter'&&ev.target.matches('.graph-node'))openEntry(ev.target.dataset.open);});
function bindView(){
 $('#map-select')?.addEventListener('change',ev=>{mapId=ev.target.value;mapMode='';pendingPoints=[];shell();});
 $('#board-select')?.addEventListener('change',ev=>{boardId=ev.target.value;shell();});
 $('#month-select')?.addEventListener('change',ev=>{calendarMonth=Number(ev.target.value);shell();});
 $('#year-input')?.addEventListener('change',ev=>{const n=Number(ev.target.value);if(Number.isInteger(n)&&Math.abs(n)<=1000000){calendarYear=n;shell();}else toast('Use a whole-number year between -1000000 and 1000000.');});
 $('#world-form')?.addEventListener('submit',ev=>{ev.preventDefault();const f=new FormData(ev.currentTarget);if(!f.get('name').trim())return;w.name=f.get('name').trim();w.description=f.get('description');change();shell();toast('World details saved.');});
 const stage=$('#map-stage');if(stage){stage.addEventListener('click',ev=>{
  if(!mapMode||ev.target.closest('.pin'))return;const rect=stage.getBoundingClientRect(),p={x:Math.max(0,Math.min(100,(ev.clientX-rect.left)/rect.width*100)),y:Math.max(0,Math.min(100,(ev.clientY-rect.top)/rect.height*100))};
  if(mapMode==='region'){pendingPoints.push(p);shell();return;}if(!w.entities.length){toast('Create an entry before placing a pin.');return;}
  modal('Give this place a story.','Choose the entry this map pin will open.',`<label>World entry<select name="entity">${options()}</select></label>`,f=>{currentMap().pins.push({id:uid(),entity:f.get('entity'),...p});mapMode='';dialog.close();change();shell();},'Place pin');
 });$$('.pin',stage).forEach(pin=>{let moved=false;pin.addEventListener('pointerdown',ev=>{if(mapMode)return;ev.preventDefault();const p=currentMap().pins.find(p=>p.id===pin.dataset.pin),start={x:ev.clientX,y:ev.clientY},rect=stage.getBoundingClientRect();moved=false;pin.setPointerCapture(ev.pointerId);const move=e=>{if(Math.hypot(e.clientX-start.x,e.clientY-start.y)>4)moved=true;if(moved){p.x=Math.max(1,Math.min(99,(e.clientX-rect.left)/rect.width*100));p.y=Math.max(4,Math.min(97,(e.clientY-rect.top)/rect.height*100));pin.style.left=p.x+'%';pin.style.top=p.y+'%';const label=pin.nextElementSibling;label.style.left=p.x+'%';label.style.top=p.y+'%';}};const up=()=>{pin.removeEventListener('pointermove',move);pin.removeEventListener('pointerup',up);if(moved)change();else openEntry(p.entity);};pin.addEventListener('pointermove',move);pin.addEventListener('pointerup',up);});});}
 $$('[data-drag-node]').forEach(handle=>handle.addEventListener('pointerdown',ev=>{if(ev.target.closest('button'))return;ev.preventDefault();const b=currentBoard(),n=b.nodes.find(n=>n.id===handle.dataset.dragNode),el=handle.parentElement,start={x:ev.clientX,y:ev.clientY,nx:n.x,ny:n.y};handle.setPointerCapture(ev.pointerId);const move=e=>{n.x=Math.max(0,Math.min(1550,start.nx+e.clientX-start.x));n.y=Math.max(0,Math.min(1000,start.ny+e.clientY-start.y));el.style.left=n.x+'px';el.style.top=n.y+'px';$('.board-lines').innerHTML=boardLines(b);};const up=()=>{handle.removeEventListener('pointermove',move);handle.removeEventListener('pointerup',up);change();};handle.addEventListener('pointermove',move);handle.addEventListener('pointerup',up);}));
}
try{const r=await fetch('/api/world');if(!r.ok)throw Error('Could not open the local world file.');const out=await r.json();w=validateWorld(out.world);token=out.token;revision=out.revision;calendarYear=w.calendar.currentYear||0;calendarMonth=Math.min(1,w.calendar.months.length-1);shell();}catch(e){app.innerHTML=`<div class="loading"><h1>Your world couldn’t open.</h1><p>${esc(e.message)}</p><p>Check the world/world.json file or restore a file from world/backups. Your files have not been overwritten.</p></div>`;}
